using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using StarterAssets;
namespace WildernessCombat {
public sealed class WildernessEnemyWorld:MonoBehaviour {
 public WildernessEnemySettings Settings;public Transform Player;public readonly List<WildernessEnemy> Enemies=new List<WildernessEnemy>();
 readonly HashSet<WildernessEnemy> attackers=new HashSet<WildernessEnemy>();Terrain[] terrains;WildernessPlayerHealth health;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]static void ResetHook(){SceneManager.sceneLoaded-=Load;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){SceneManager.sceneLoaded+=Load;Load(SceneManager.GetActiveScene(),LoadSceneMode.Single);}
 static void Load(Scene scene,LoadSceneMode mode){if(scene.name!="MyForest")return;foreach(var root in scene.GetRootGameObjects())if(root.GetComponent<WildernessEnemyWorld>())return;var settings=Resources.Load<WildernessEnemySettings>("WildernessEnemies/Settings");if(!settings||!settings.Ready)return;var go=new GameObject("Wilderness Flying Enemies");SceneManager.MoveGameObjectToScene(go,scene);go.AddComponent<WildernessEnemyWorld>().Settings=settings;}
 void Start(){if(!Settings||!Settings.Ready){enabled=false;return;}var go=GameObject.Find("PlayerArmature");if(!go){enabled=false;return;}Player=go.transform;health=go.GetComponent<WildernessPlayerHealth>();if(!health)health=go.AddComponent<WildernessPlayerHealth>();terrains=Terrain.activeTerrains;
  var random=new System.Random(46127);for(int i=0;i<Settings.SpawnPoints.Length;i++){var point=Settings.SpawnPoints[i];if(!IsWild(point)||Vector3.Distance(point,Player.position)<18)continue;bool female=random.Next(2)==0;bool mage=i<4?i%2==0:random.Next(2)==0;if(i<4)female=i>=2;int packIndex=i<40?i/4:10+(i-40)/5;string packName="Pack "+(packIndex+1).ToString("00");var pack=transform.Find(packName);if(!pack){pack=new GameObject(packName).transform;pack.SetParent(transform);}bool cyclops=Settings.Cyclops&&Settings.CyclopsIdle&&Settings.CyclopsWalk&&Settings.CyclopsSwing&&(i<40?i%4==0:(i-40)%5==0);if(cyclops)mage=false;var root=new GameObject(cyclops?"Cyclops Wilderness Brute":(female?"Female":"Male")+(mage?" Wilderness Mage":" Wilderness Sword"));root.transform.SetParent(pack);root.transform.position=point+Vector3.up*.55f;var enemy=root.AddComponent<WildernessEnemy>();Enemies.Add(enemy);enemy.Initialize(this,cyclops?Settings.Cyclops:female?Settings.Female:Settings.Male,mage,point,i*.73f,cyclops);}}
 public int RebuildCyclopes(){if(!Settings||!Settings.Cyclops)return 0;int count=0;foreach(var old in Enemies.ToArray()){if(!old||!old.Cyclops)continue;var home=old.Home;var parent=old.transform.parent;EndAttack(old);old.gameObject.SetActive(false);Enemies.Remove(old);Destroy(old.gameObject);var go=new GameObject("Cyclops Wilderness Brute");go.transform.SetParent(parent);go.transform.position=home;var enemy=go.AddComponent<WildernessEnemy>();Enemies.Add(enemy);enemy.Initialize(this,Settings.Cyclops,false,home,count*.73f,true);count++;}return count;}
 public bool PlayerSafe=>!Player||!IsWild(Player.position)||QueenBattle.QueenBossBattle.BattleActive||DomainInteractionState.IsModal;
 public bool IsWild(Vector3 p){if(Settings.CitySafeZones!=null)foreach(var b in Settings.CitySafeZones)if(p.x>=b.min.x&&p.x<=b.max.x&&p.z>=b.min.z&&p.z<=b.max.z)return false;return true;}
 public float Ground(Vector3 p){if(terrains!=null)foreach(var t in terrains){var o=t.transform.position;var size=t.terrainData.size;if(p.x>=o.x&&p.x<=o.x+size.x&&p.z>=o.z&&p.z<=o.z+size.z)return t.SampleHeight(p)+o.y;}return p.y-.55f;}
 public bool BeginAttack(WildernessEnemy enemy){attackers.RemoveWhere(e=>!e||!e.isActiveAndEnabled);return attackers.Contains(enemy)||attackers.Count<3&&attackers.Add(enemy);}
 public void EndAttack(WildernessEnemy enemy){attackers.Remove(enemy);}
 public void HurtPlayer(float damage,Vector3? attackerPosition=null){if(health&&!PlayerSafe)health.Receive(damage,attackerPosition);}
 public Vector3 Separation(WildernessEnemy enemy){Vector3 push=Vector3.zero;foreach(var e in Enemies){if(!e||e==enemy||!e.IsDamageable)continue;Vector3 d=enemy.transform.position-e.transform.position;d.y=0;float dist=d.magnitude;if(dist>.01f&&dist<1.8f)push+=d/dist*(1.8f-dist);}return Vector3.ClampMagnitude(push,1.4f);}
 public bool ClearLine(Vector3 from,Vector3 to,Transform owner){var delta=to-from;if(delta.sqrMagnitude<.001f)return true;foreach(var h in Physics.RaycastAll(from,delta.normalized,delta.magnitude,~0,QueryTriggerInteraction.Ignore)){if(h.transform.IsChildOf(owner)||h.transform.IsChildOf(Player))continue;if(h.collider.GetComponentInParent<WildernessEnemy>())continue;return false;}return true;}
}}

